
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbek1_vdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbek1_vdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.304630398496668e+00, -4.222981083463120e+00, -4.108688981938712e+00, -3.950615027122829e+00, -3.735745635404653e+00, -3.450887068093485e+00, -3.086601593369397e+00, -2.644187430679212e+00, -2.144254154881613e+00, -1.625150173862498e+00, -1.103438895310090e+00, -7.106286609195227e-01, -6.021820179060844e-01, -5.018389010231866e-01, -3.724859459890172e-01, -2.481653419865376e-01, -1.418486385536231e-01, -5.451852539074067e-02, -1.198243666797674e-02, -1.348333317707567e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


